const displayTax = async () => {
  const totalTax = this.getValue("pr_total_tax_fee");

  if (totalTax > 0.0) {
    this.display(["pr_total_tax_fee", "total_tax_currency"]);
  }
};

const enabledUOMField = async () => {
  const tablePR = this.getValue("table_pr");

  tablePR.forEach((pr, rowIndex) => {
    if (pr.pr_line_material_id) {
      this.triggerEvent("onChange_item_fetch_uom", {
        prItem: pr,
        index: rowIndex,
      });
      this.disabled([`table_pr.${rowIndex}.pr_line_uom_id`], false);
    }
  });
};

const setPlant = (organizationId, pageStatus, data) => {
  const currentDept = this.getVarSystem("deptIds").split(",")[0];

  if (currentDept === organizationId) {
    this.disabled(["plant_id"], false);
    if (pageStatus === "Add" || pageStatus === "Clone") {
      data["plant_id"] = currentDept;
    }
  } else {
    this.disabled(["plant_id"], true);

    if (pageStatus === "Add" || pageStatus === "Clone") {
      data["plant_id"] = currentDept;
    }
  }

  return data;
};

const checkAccIntegrationType = async (organizationId, data) => {
  if (organizationId) {
    const resAI = await db
      .collection("accounting_integration")
      .where({ organization_id: organizationId })
      .get();

    if (resAI && resAI.data.length > 0) {
      const aiData = resAI.data[0];
      data["acc_integration_type"] = aiData.acc_integration_type;
    }
  }

  return data;
};

(async () => {
  try {
    const status = await this.getValue("preq_status");
    const data = {};

    const pageStatus = this.isAdd
      ? "Add"
      : this.isEdit
        ? "Edit"
        : this.isView
          ? "View"
          : this.isCopy
            ? "Clone"
            : (() => {
                this.$message.error("Invalid page status");
              })();

    let organizationId = this.getVarGlobal("firstLvDeptId");

    data["page_status"] = pageStatus;

    this.hide([
      "exchange_rate",
      "exchange_rate_myr",
      "exchange_rate_currency",
      "myr_total_amount",
      "total_amount_myr",
    ]);

    switch (pageStatus) {
      case "Add":
        await setPlant(organizationId, pageStatus, data);
        await checkAccIntegrationType(organizationId, data);

        this.display(["draft_status"]);
        data["organization_id"] = organizationId;
        data["pr_date"] = new Date().toISOString().split("T")[0];
        data["supplier_type"] = "Existing Supplier";
        data["preq_type"] = "Standard";
        this.setOptionData("preq_type", [
          { label: "Standard", value: "Standard" },
          { label: "Contract", value: "Contract" },
        ]);

        break;

      case "Edit":
        const preqData = this.getValues();
        await disabledEditField(status);
        await showStatusHTML(status);
        await enabledUOMField();
        await displayCurrency();
        await displaySupplierType();
        await displayPlantAddress();
        await displayTax();
        await setPlant(organizationId, pageStatus, data);
        if (status !== "Draft") {
          this.disabled(["pr_no", "document_no_format"], true);
        }
        data["previous_status"] = this.getValue("preq_status");
        if (preqData.preq_type === "Planning") {
          this.disabled(["preq_type"], true);
        } else {
          this.disabled(["preq_type"], false);
          this.setOptionData("preq_type", [
            { label: "Standard", value: "Standard" },
            { label: "Contract", value: "Contract" },
          ]);
        }
        break;

      case "Clone":
        this.display(["draft_status"]);
        this.disabled(
          this.getValue("pr_no_type") !== -9999 ? "pr_no" : "",
          true,
        );
        // if(this.getValue("pr_no_type") !== -9999){
        //   this.disabled( "pr_no",true)
        // }
        await setPlant(organizationId, pageStatus, data);
        await enabledUOMField();
        await checkAccIntegrationType(organizationId, data);
        data["organization_id"] = organizationId;
        data["pr_date"] = new Date().toISOString().split("T")[0];
        data["pr_no"] = null;
        data["preq_status"] = null;
        data["preq_type"] = "Standard";
        data["previous_status"] = "";
        data[`table_pr.order_qty`] = 0;
        data[`table_pr.po_id`] = [];
        data[`table_pr.po_line_id`] = [];
        data["pr_requestor"] = this.getVarGlobal("nickname");

        await displayCurrency();
        await displaySupplierType();
        await displayPlantAddress();
        await displayTax();
        break;

      case "View":
        this.hide([
          "link_billing_address",
          "link_shipping_address",
          "button_save_as_draft",
          "button_save_as_issue",
        ]);
        await showStatusHTML(status);
        await displayCurrency();
        await displaySupplierType();
        await displayPlantAddress();
        await displayTax();

        break;
    }

    this.setData(data);
    this.refreshFieldOptionData("plant_id");
  } catch (error) {
    this.$message.error(error || error.toString());
    console.error(error);
  }
})();

setTimeout(async () => {
  const maxRetries = 10;
  const interval = 500;
  for (let i = 0; i < maxRetries; i++) {
    const op = await this.onDropdownVisible("pr_no_type", true);
    if (op != null) break;
    await new Promise((resolve) => setTimeout(resolve, interval));
  }
  function getDefaultItem(arr) {
    return arr?.find((item) => item?.item?.is_default === 1);
  }
  var params = this.getComponent("pr_no");
  const { options } = params;

  const optionsData = this.getOptionData("pr_no_type") || [];
  const defaultData = getDefaultItem(optionsData);
  if (options?.canManualInput) {
    this.setOptionData("pr_no_type", [
      { label: "Manual Input", value: -9999 },
      ...optionsData,
    ]);
    if (this.isAdd) {
      this.setData({
        pr_no_type: defaultData ? defaultData.value : -9999,
      });
    }
  } else if (defaultData) {
    if (this.isAdd) {
      this.setData({ pr_no_type: defaultData.value });
    }
  }
}, 200);

const data = this.getValues();
const items = data.table_pr;
const exchangeRate = data.exchange_rate;
const updatedData = {};
let totalGross = 0;
let totalDiscount = 0;
let totalTax = 0;
let totalAmount = 0;

const roundPrice = (value) => {
  return parseFloat(parseFloat(value || 0).toFixed(4));
};

if (Array.isArray(items)) {
  items.forEach((item, index) => {
    console.log("item", item);
    const quantity = Number(item.pr_line_qty) || 0;
    const unitPrice = roundPrice(item.pr_line_unit_price) || 0;
    const grossValue = quantity * unitPrice;

    totalGross += roundPrice(grossValue);

    updatedData[`table_pr.${index}.pr_line_gross`] = roundPrice(grossValue);
    updatedData[`table_pr.${index}.pr_line_amount`] = roundPrice(grossValue);
    updatedData["pr_sub_total"] = roundPrice(totalGross);

    let discount = parseFloat(item.pr_line_discount) || 0;
    let discountUOM = item.pr_line_discount_uom;
    let discountAmount = 0.0;
    const taxRate = Number(item.pr_line_taxes_percent) || 0;
    const taxInclusive = item.pr_tax_inclusive;

    if (discount > 0) {
      if (!discountUOM) {
        discountUOM = "Amount";
        updatedData[`table_pr.${index}.pr_line_discount_uom`] = "Amount";
      }
    }

    if (discountUOM) {
      if (discount !== 0) {
        if (discountUOM === "Amount") {
          discountAmount = roundPrice(discount);
        } else if (discountUOM === "%") {
          discountAmount = roundPrice((grossValue * discount) / 100);
        }

        if (discountAmount > grossValue) {
          discount = 0;
          discountAmount = 0;

          updatedData[`table_pr.${index}.pr_line_discount`] = 0;
          updatedData[`table_pr.${index}.pr_line_discount_amount`] = 0;
        } else {
          updatedData[`table_pr.${index}.pr_line_discount_amount`] =
            roundPrice(discountAmount);
        }
      }
    } else {
      updatedData[`table_pr.${index}.pr_line_discount_amount`] = 0;
    }

    const amountAfterDiscount = roundPrice(grossValue - discountAmount);

    let taxAmount = 0;
    let finalAmount = amountAfterDiscount;

    if (taxRate) {
      const taxRateDecimal = taxRate / 100;

      if (taxInclusive === 1) {
        taxAmount = roundPrice(
          amountAfterDiscount - amountAfterDiscount / (1 + taxRateDecimal),
        );
        finalAmount = amountAfterDiscount;
      } else {
        taxAmount = roundPrice(amountAfterDiscount * taxRateDecimal);
        finalAmount = amountAfterDiscount + taxAmount;
      }

      updatedData[`table_pr.${index}.pr_line_tax_fee_amount`] =
        roundPrice(taxAmount);
    } else {
      updatedData[`table_pr.${index}.pr_line_tax_fee_amount`] = 0;
    }

    updatedData[`table_pr.${index}.pr_line_amount`] = roundPrice(finalAmount);

    totalDiscount += roundPrice(discountAmount);
    totalTax += roundPrice(taxAmount);
    totalAmount += roundPrice(finalAmount);

    if (totalTax > 0) {
      this.display(["pr_total_tax_fee", "total_tax_currency"]);
    }

    updatedData["pr_discount_total"] = roundPrice(totalDiscount);
    updatedData["pr_total_tax_fee"] = roundPrice(totalTax);
    updatedData["pr_total_price"] = roundPrice(totalAmount);

    const myrTotalAmount = (exchangeRate || 1) * totalAmount;
    updatedData["myr_total_amount"] = roundPrice(myrTotalAmount);
  });

  this.setData(updatedData);
} else {
  console.log("Not an array:", items);
}

