(async () => {
  const data = this.getValues();
  const plant = this.getValue('plant_id');

  if (plant) {
      this.display('grid_preq_address');
      await resetAddrFields();

      const [resShipping, resPlant] = await Promise.all([
          db.collection('address_purpose').where({ purpose_name: 'Shipping' }).get(),
          db.collection('plant_address').where({ plant_id: plant, is_default: 1 }).get(), ])

      if (resPlant.data.length === 0 || resShipping.data.length === 0) return;

      const addresses = resPlant.data;
      const shippingAddrId = resShipping.data[0].id;

      addresses.forEach(async (address) => {

        let country = '';
        let state = '';

        if(address.address_country_id) {
            const resCountry = await db.collection("country").where({ id: address.address_country_id }).get();
            country = resCountry?.data[0]?.country_name || '';
        }

        if(address.address_state) {
            const resState = await db.collection("state").where({ id: address.address_state }).get();
            state = resState?.data[0]?.state_name || '';
        }


        const isShipping = address.plant_purpose === shippingAddrId;
        const addressType = isShipping ? 'shipping' : 'billing';
        const addressTypeUpperCase = isShipping ? "Shipping" : "Billing";

        const addressLines = [
          address.address_line_1,
          address.address_line_2,
          address.address_line_3,
          address.address_line_4,
        ]
        .filter((line) => line) 
        .join(
          ([address.address_line_1, address.address_line_2, address.address_line_3, address.address_line_4]
            .filter((line) => line)
            .pop() || "").endsWith(",") ? " " : ", "
        );

        const cityDetails = [
          address.address_city,
          address.address_postal_code,
          address.address_state ? state : '',
          address.address_country_id ? country : ""
        ]
        .filter((detail) => detail) 
        .join(
          ([address.address_city, address.address_postal_code, address.address_state ? state : '', address.address_country_id ? country : ""]
            .filter((detail) => detail)
            .pop() || "").endsWith(",") ? " " : ", "
        );

        const addressAttention = address.address_attention ? '\nAttention: ' + address.address_attention : ''

        const addressPurposeName =`\n${addressTypeUpperCase}` + ' Address';

          const addressPersonParts = [
          address.address_name,
          address.address_phone
          ].filter((part) => part); // Remove undefined or null
          const addressPerson = addressPersonParts.length > 0 ? addressPersonParts.join(' | ') : '';

        const formattedAddress = [
          addressPerson,
          addressPurposeName,
          addressLines,
          cityDetails,
          addressAttention
        ].filter(Boolean).join('\n');

          setAddressFields(
          addressType,
          address
          );

          if(addressType === 'shipping') {
            this.setData({ 'preq_shipping_address': formattedAddress });
          } else {
          this.setData({ 
            'preq_billing_address': formattedAddress, 
            });
          }
      })
  }
})();

// Pick the description this supplier has bound to the item on the Item master.
// Reads table_sup_item_bind (supplier_id / item_description) -- NOT the customer
// twin. An item may carry several rows for the same supplier: take the first one
// that actually has a description. Falls back to the item's own material_desc.
const resolveItemDesc = (item, supplierId) => {
  const fallback = item?.material_desc || "";
  if (!supplierId || Array.isArray(supplierId)) return fallback;

  const binds = Array.isArray(item?.table_sup_item_bind)
    ? item.table_sup_item_bind
    : [];
  const wanted = String(supplierId).trim();

  for (const row of binds) {
    if (!row) continue;
    if (String(row.supplier_id ?? "").trim() !== wanted) continue;
    const desc = String(row.item_description ?? "").trim();
    if (desc) return desc;
  }

  return fallback;
};

const fetchLatestPricing = async (
  result,
  overwrite,
  itemById,
  itemIdByLine,
  supplierId,
) => {
  const updates = {};
  for (const item of result) {
    if (overwrite === "Yes") {
      updates[`table_pr.${item.line_index}.pr_line_unit_price`] =
        item.unit_price;
      updates[`table_pr.${item.line_index}.pr_line_uom_id`] = item.uom_id;
      updates[`table_pr.${item.line_index}.pr_line_tax_rate_id`] =
        item.tax_rate;
      updates[`table_pr.${item.line_index}.pr_line_taxes_percent`] =
        item.tax_percent;
      updates[`table_pr.${item.line_index}.from_historical`] =
        item.from_historical;
